pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address to, uint256 loanID) public {
        // Bound loanID to avoid array out-of-bounds
        loanID = bound(loanID, 0, type(uint256).max);
        // Attempt to call approveTransfer, which reverts if msg.sender != loan.lender
        // We don't care about revert; we just need a call that reads owner() internally
        vm.assume(to != address(0));
        // The bug changes owner() to return the collateral address.
        // In the reference, owner() returns the immutable arg at offset 0x0.
        // We can't directly read the immutable arg, but we can observe that
        // owner() must not return the collateral address (or any other deterministic value
        // that could be the collateral). Since we cannot call collateral() in the same context
        // as owner() is called internally, we simply assert that approveTransfer
        // uses owner() correctly. However, the simplest general rule is:
        // If we call approveTransfer with a specific to address, and it succeeds,
        // then the lender of the loan is the original owner (which was set at construction).
        // But we don't have access to the original owner. So we assert that
        // the call doesn't revert with a specific known error that would indicate
        // the wrong owner check.
        // Alternative: the bug causes owner() to return the collateral address.
        // Then, in approveTransfer, the check msg.sender != loans[loanID_].lender
        // might still pass if loans[loanID_].lender happens to equal the collateral address.
        // But we can't know that. So we write a rule that holds for all inputs:
        // The call to approveTransfer should not revert with "OnlyApproved"
        // when msg.sender is the loan's lender. Since we cannot set up loans easily,
        // we instead check that the owner() function returns the same value as
        // the address at immutable offset 0x0, but we can only approximate.
        // Let's use a different approach: We'll call owner() directly and compare
        // with the address we expect (the owner's address, which we cannot know).
        // Instead, we assert that owner() is not equal to the collateral address.
        // But that's too specific. Let's try:
        // The bug makes owner() return collateral(). So, if we call owner() and collateral(),
        // they should differ in the reference but be equal in the buggy version.
        // That's a simple test.

        address ownerVal = c.owner();
        address collateralVal = address(c.collateral());

        // In the reference, owner() is at offset 0x0, collateral at offset 0x14, so they differ.
        // In the bug, owner() also returns collateral, so they are equal.
        assertTrue(ownerVal != collateralVal, "owner() should not equal collateral()");
    }
}

