pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lender, address borrower, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        vm.assume(lender != address(0) && lender != borrower);
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(interest > 0 && interest < 1e18);
        vm.assume(loanToCollateral > 0 && loanToCollateral < 1e18);
        vm.assume(duration > 0 && duration < 365 days);

        // Request loan as borrower
        vm.prank(borrower);
        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        // Clear request as lender
        vm.prank(lender);
        uint256 loanID = c.clearRequest(reqID, false, false);

        // Approve transfer from lender to some address
        vm.prank(lender);
        c.approveTransfer(borrower, loanID);

        // Transfer ownership - this will set lender to borrower
        vm.prank(borrower);
        c.transferOwnership(loanID);

        // Now call approveTransfer with the new lender (borrower) - should succeed
        // After transferOwnership, the lender is borrower
        // But if owner() returns collateral address (bug), approveTransfer will fail
        // because owner() is checked in some functions indirectly

        // The general rule: after transferOwnership, the new lender (borrower) should be able to call approveTransfer
        // If owner() is wrong, the approval will set wrong address
        vm.prank(borrower);
        c.approveTransfer(lender, loanID);

        // The rule: The owner() function should return the borrower (original owner from immutable args)
        // After transferOwnership, the lender is changed but owner() still returns the same
        // This should be consistent
        assertTrue(c.owner() != address(0), "Owner should not be zero");
    }
}

